t.script:
(function() {
    const deviceToken = '';
    const baseUrl = '';
    let map = null;
    let marker = null;

    // 初始化地圖
    function initMap(lat, lng) {
        // 優先使用 Google Maps（如果有 API Key），否則使用 OpenStreetMap
        const googleMapsApiKey = '';

        if (googleMapsApiKey) {
            // 使用 Google Maps（Google 非營利組織免費額度）
            const mapUrl = `https://www.google.com/maps/embed/v1/place?key=${googleMapsApiKey}&q=${lat},${lng}&zoom=15`;
            const mapContainer = document.getElementById('map-container');
            mapContainer.innerHTML = '<iframe width="100%" height="100%" frameborder="0" style="border:0" src="' + mapUrl + '" allowfullscreen></iframe>';
        } else {
            // 備選：使用 OpenStreetMap (免費，無需 API Key)
            const mapUrl = `https://www.openstreetmap.org/export/embed.html?bbox=${lng-0.01},${lat-0.01},${lng+0.01},${lat+0.01}&layer=mapnik&marker=${lat},${lng}`;
            const mapContainer = document.getElementById('map-container');
            mapContainer.innerHTML = `<iframe width="100%" height="100%" frameborder="0" scrolling="no" marginheight="0" marginwidth="0" src="${mapUrl}"></iframe>`;
        }
    }

    // 取得目前位置
    function getCurrentLocation() {
        const btn = document.getElementById('get-location-btn');
        btn.disabled = true;
        btn.textContent = '定位中...';

        if (!navigator.geolocation) {
            alert('您的瀏覽器不支援地理位置功能');
            btn.disabled = false;
            btn.textContent = '📍 取得目前位置';
            return;
        }

        navigator.geolocation.getCurrentPosition(
            function(position) {
                const lat = position.coords.latitude;
                const lng = position.coords.longitude;

                // 更新顯示
                document.getElementById('latitude-display').textContent = lat.toFixed(7);
                document.getElementById('longitude-display').textContent = lng.toFixed(7);

                // 更新地圖
                initMap(lat, lng);

                // 反向地理編碼（取得地址）
                // 優先使用 Google Geocoding API，否則使用 OpenStreetMap Nominatim
                const googleMapsApiKey = '';

                if (googleMapsApiKey) {
                    // 使用 Google Geocoding API（Google 非營利組織免費額度）
                    fetch(`https://maps.googleapis.com/maps/api/geocode/json?latlng=${lat},${lng}&key=${googleMapsApiKey}&language=zh-TW`)
                        .then(response => response.json())
                        .then(data => {
                            const address = data.results && data.results[0] ? data.results[0].formatted_address : '無法取得地址';
                            document.getElementById('address-display').textContent = address;

                            // 發送到伺服器
                            updateLocationOnServer(lat, lng, address);
                        })
                        .catch(error => {
                            console.error('Google 地理編碼失敗:', error);
                            // 備選：使用 OpenStreetMap
                            fetchOpenStreetMapAddress(lat, lng);
                        });
                } else {
                    // 備選：使用 OpenStreetMap Nominatim
                    fetchOpenStreetMapAddress(lat, lng);
                }

                function fetchOpenStreetMapAddress(lat, lng) {
                    fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lng}`)
                        .then(response => response.json())
                        .then(data => {
                            const address = data.display_name || '無法取得地址';
                            document.getElementById('address-display').textContent = address;

                            // 發送到伺服器
                            updateLocationOnServer(lat, lng, address);
                        })
                        .catch(error => {
                            console.error('取得地址失敗:', error);
                            updateLocationOnServer(lat, lng, '');
                        });
                }

                btn.disabled = false;
                btn.textContent = '📍 更新位置';
            },
            function(error) {
                let errorMsg = '無法取得位置';
                switch(error.code) {
                    case error.PERMISSION_DENIED:
                        errorMsg = '使用者拒絕提供地理位置';
                        break;
                    case error.POSITION_UNAVAILABLE:
                        errorMsg = '位置資訊不可用';
                        break;
                    case error.TIMEOUT:
                        errorMsg = '取得位置超時';
                        break;
                }
                alert(errorMsg);
                btn.disabled = false;
                btn.textContent = '📍 取得目前位置';
            },
            {
                enableHighAccuracy: true,
                timeout: 10000,
                maximumAge: 0
            }
        );
    }

    // 更新位置到伺服器
    function updateLocationOnServer(lat, lng, address) {
        fetch(`${baseUrl}/device/${deviceToken}/location`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({
                latitude: lat,
                longitude: lng,
                address: address
            })
        })
        .then(response => response.json())
        .then(data => {
            if (data.status === 'success') {
                console.log('位置已更新到伺服器');
            } else {
                console.error('更新位置失敗:', data.message);
            }
        })
        .catch(error => {
            console.error('發送位置失敗:', error);
        });
    }

    // 綁定按鈕事件
    document.getElementById('get-location-btn').addEventListener('click', getCurrentLocation);

    // 如果有初始位置，載入地圖
    const initialLat = ;
    const initialLng = ;
    if (initialLat !== 0 && initialLng !== 0) {
        initMap(initialLat, initialLng);
    }

    // 定期更新位置（每 5 分鐘）
    setInterval(function() {
        if (navigator.geolocation) {
            navigator.geolocation.getCurrentPosition(
                function(position) {
                    updateLocationOnServer(
                        position.coords.latitude,
                        position.coords.longitude,
                        ''
                    );
                },
                function(error) {
                    console.log('定期更新位置失敗:', error);
                }
            );
        }
    }, 5 * 60 * 1000); // 5 分鐘
})();
